cd /user/user1/harbor-runs/efb425739ec9/workspace; python3 -c "
import json
from collections import defaultdict, Counter
traj=defaultdict(list)
for r in open('observed_run/tool_traces.jsonl'):
    r=json.loads(r); traj[r['trajectory_id']].append(r)
grade={}
for tid,evts in traj.items():
    for e in evts:
        if e['event']=='grade':
            grade[tid]=(e['reward'], e['case_id'], e['call'])
# eval rollouts give trajectory_ids (4 each). map to cases/rewards
rolls=[json.loads(l) for l in open('observed_run/rollouts.jsonl')]
for r in rolls:
    if r['mode']=='eval':
        tids=r['trajectory_ids']
        info=[grade.get(t) for t in tids]
        print('eval step', r['step'], '->', info)
    else:
        tids=r['trajectory_ids']
        rew=Counter(grade.get(t,(None,None,None))[1] for t in tids)
        print('train step', r['step'], 'cases:', dict(rew))
"

